from textutil.truncate import truncate


def test_short_text_untouched():
    assert truncate("short", 10) == "short"


def test_word_boundary():
    assert truncate("The quick brown fox jumps", 15) == "The quick..."


def test_within_limit():
    assert len(truncate("alpha beta gamma delta", 12)) <= 12


def test_never_splits_a_word():
    # "The quick bro..." would split "brown"; must back off to last whole word.
    assert truncate("The quick brown fox jumps", 17) == "The quick..."


def test_result_within_limit_on_word_boundary():
    out = truncate("alpha beta gamma delta", 12)
    assert out == "alpha..."
    assert len(out) <= 12
